def build_guide_pages():
    pages = {}
    slugs = list(GUIDE_SPECS)
    for index, (slug, (title, description, intro, sections)) in enumerate(GUIDE_SPECS.items()):
        related = [slugs[(index + 1) % len(slugs)], slugs[(index + 3) % len(slugs)], "faq"]
        pages[slug] = page(title, description, "Career Guide", intro, sections + GUIDE_CLOSERS, related)
    return pages


def build_profession_pages():
    pages = {}
    slugs = list(PROFESSIONS)
    for i, (slug, (title, role, purpose, skills, metrics, example)) in enumerate(PROFESSIONS.items()):
        pages[slug] = page(title, f"Create an ATS-friendly {role.lower()} resume with relevant skills, achievement examples, structure, and tailoring guidance.", "Resume by Profession",
            f"A strong {role.lower()} resume connects real experience to {purpose}. Use this guide to choose evidence, terminology, and metrics without copying generic content.", [
                (f"What employers need from a {role}", f"Start with the outcomes described in the posting, not a generic list of traits. Identify the environments, customers, systems, constraints, and collaborators involved in the work. Build a requirement-to-evidence map and make the strongest supported match visible in the summary and first experience bullets."),
                ("Skills to demonstrate", f"Relevant terms may include {skills}. A keyword belongs on the resume only when you can explain how and where you used it. Place important capabilities in context within achievements; use the skills section as a concise index rather than the only evidence."),
                ("Results and scope", f"Useful measures may include {metrics}. Verify every figure. If a commercial number is confidential or unavailable, describe the delivered change, operating scale, stakeholder adoption, quality improvement, or documented process result."),
                ("Example positioning", example + " This sentence is a structural example, not content to copy. Replace it with your actual action, environment, scope, and outcome."),
                ("Recommended structure", "Use a specific professional summary, core skills, reverse-chronological experience, selected projects when relevant, and education or certifications. Keep one main column, ordinary headings, selectable text, consistent dates, and a professional filename. Link to a portfolio only when it adds credible evidence."),
                ("Tailoring checklist", f"Confirm that the exact {role.lower()} title is clear, mandatory qualifications are visible when possessed, and the first half of the page contains the strongest evidence. Compare the exported text with the job description, remove unsupported language, proofread links and dates, and prepare to discuss every highlighted result."),
            ], related=(slugs[(i+1)%len(slugs)], "tailor-resume-job-description", "resume-templates-guide"))
    return pages


